$webp$, chr(10), '') AS header_image
), posts AS (
  INSERT INTO news_posts (category, is_test, header_image)
  SELECT 'game', modes.is_test, artwork.header_image
  FROM (VALUES (false), (true)) AS modes(is_test) CROSS JOIN artwork
  RETURNING id
)
INSERT INTO news_translations (post_id, locale, title, intro, body, header_alt)
SELECT posts.id, copy.locale, copy.title, copy.intro, copy.body, copy.header_alt
FROM posts CROSS JOIN (VALUES
  ('en', 'Nonograms joins the library',
   'Aviarium has a new game. In Nonograms, the clues at the edge of the grid tell you which squares to fill. Solve the puzzle to reveal a picture.',
   'Open Nonograms in the library and start with Sulphur-crested Cockatoos. The pack has five puzzles, from a small cockatoo egg to a bird in flight. You can also generate 5 × 5 or 10 × 10 puzzles at three difficulty levels in Quick Play. Open the game once online to download it for offline play.',
   'A sulphur-crested cockatoo in flight against a blue sky.'),
  ('nl', 'Nonogrammen in de bibliotheek',
   'Aviarium heeft een nieuw spel. Bij nonogrammen vertellen de aanwijzingen aan de rand van het rooster welke vakjes je moet vullen. Los de puzzel op om een afbeelding te onthullen.',
   'Open Nonogrammen in de bibliotheek en begin met Grote geelkuifkaketoes. Dit pakket bevat vijf puzzels, van een klein kaketoe-ei tot een vogel in volle vlucht. Met Snel spelen genereer je ook puzzels van 5 × 5 of 10 × 10 op drie moeilijkheidsniveaus. Open het spel eenmaal online om het te downloaden voor offline spelen.',
   'Een grote geelkuifkaketoe vliegt tegen een blauwe lucht.')
) AS copy(locale, title, intro, body, header_alt);
